// Validate diagrams via Kroki and format output
const input = $input.first().json;
let output = input.output || input.response || input.text || input.content || '';

let parsed;
try {
  const mdMatch = output.match(/```json\n([\s\S]*?)\n```/) || output.match(/```\n([\s\S]*?)\n```/);
  if (mdMatch && mdMatch[1]) parsed = JSON.parse(mdMatch[1].trim());
  else {
    const jsonMatch = output.match(/\{[\s\S]*\}/);
    if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
    else parsed = JSON.parse(output);
  }
} catch (e) {
  return [{
    json: {
      valid: false,
      error: 'Parse error: ' + e.message,
      raw_output: output.substring(0, 3000),
      architecture_diagram: '',
      data_flow_diagram: '',
      er_diagram: '',
      sequence_diagram: '',
      validation_status: { architecture: false, data_flow: false, er: false, sequence: false }
    }
  }];
}

// Ensure fields exist
if (!parsed.architecture_diagram) parsed.architecture_diagram = '';
if (!parsed.data_flow_diagram) parsed.data_flow_diagram = '';
if (!parsed.er_diagram) parsed.er_diagram = '';
if (!parsed.sequence_diagram) parsed.sequence_diagram = '';
if (!parsed.validation_status) parsed.validation_status = { architecture: false, data_flow: false, er: false, sequence: false };

// Non-deterministic validation: check that diagrams are non-empty and look like Mermaid
const validate = (diag) => {
  if (!diag || diag.trim().length < 10) return false;
  const hasMermaidKeywords = /^(flowchart|graph|erDiagram|sequenceDiagram|classDiagram|stateDiagram)/m.test(diag.trim());
  return hasMermaidKeywords;
};

parsed.validation_status = {
  architecture: validate(parsed.architecture_diagram),
  data_flow: validate(parsed.data_flow_diagram),
  er: validate(parsed.er_diagram),
  sequence: validate(parsed.sequence_diagram)
};

return [{ json: { valid: true, ...parsed } }];
